package com.example.insurance.controller.user;import com.example.insurance.entity.Policy;import com.example.insurance.service.PolicyService;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/customer/customers") public class CustomerPolicyController {private final PolicyService s;public CustomerPolicyController(PolicyService s){this.s=s;}@GetMapping("/{id}/policy") public Policy policy(@PathVariable Long id){return s.getByCustomerId(id);}}